 87→func (c *Claude) Bootstrap() error {
 88→	// On CI, write a config file so Claude Code uses the API key from the
 89→	// environment instead of trying OAuth/Keychain.
 90→	if os.Getenv("CI") == "" {
 91→		return nil
 92→	}
 93→	apiKey := os.Getenv("ANTHROPIC_API_KEY")
 94→	if apiKey == "" {
 95→		return nil
 96→	}
 97→	home, err := os.UserHomeDir()
 98→	if err != nil {
 99→		return fmt.Errorf("get home dir: %w", err)
100→	}
101→	dir := filepath.Join(home, ".claude")
102→	if err := os.MkdirAll(dir, 0o755); err != nil {
103→		return fmt.Errorf("mkdir %s: %w", dir, err)
104→	}
105→	config := fmt.Sprintf(`{"primaryApiKey":%q,"hasCompletedOnboarding":true}`, apiKey)
106→	path := filepath.Join(dir, ".claude.json")
107→	return os.WriteFile(path, []byte(config), 0o644)
108→}
