 53→// resolveTranscriptRef returns the transcript path from the hook input, or computes
 54→// it dynamically when the hook doesn't provide one (Cursor CLI pattern).
 55→func (c *CursorAgent) resolveTranscriptRef(ctx context.Context, conversationID, rawPath string) string {
 56→	if rawPath != "" {
 57→		return rawPath
 58→	}
 59→
 60→	repoRoot, err := paths.WorktreeRoot(ctx)
 61→	if err != nil {
 62→		logging.Warn(ctx, "cursor: failed to get worktree root for transcript resolution", "err", err)
 63→		return ""
 64→	}
 65→
 66→	sessionDir, err := c.GetSessionDir(repoRoot)
 67→	if err != nil {
 68→		logging.Warn(ctx, "cursor: failed to get session dir for transcript resolution", "err", err)
 69→		return ""
 70→	}
 71→
 72→	return c.ResolveSessionFile(sessionDir, conversationID)
 73→}
