 91→// GetSessionDir returns the directory where Cursor stores session transcripts.
 92→func (c *CursorAgent) GetSessionDir(repoPath string) (string, error) {
 93→	if override := os.Getenv("ENTIRE_TEST_CURSOR_PROJECT_DIR"); override != "" {
 94→		return override, nil
 95→	}
 96→
 97→	homeDir, err := os.UserHomeDir()
 98→	if err != nil {
 99→		return "", fmt.Errorf("failed to get home directory: %w", err)
100→	}
101→
102→	projectDir := sanitizePathForCursor(repoPath)
103→	return filepath.Join(homeDir, ".cursor", "projects", projectDir, "agent-transcripts"), nil
104→}
105→
106→// ReadSession reads a session from Cursor's storage (JSONL transcript file).
107→// Note: ModifiedFiles is left empty because Cursor's transcript format does not
108→// contain tool_use blocks. File detection relies on git status instead.
109→func (c *CursorAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
110→	if input.SessionRef == "" {
111→		return nil, errors.New("session reference (transcript path) is required")
112→	}
113→
114→	data, err := os.ReadFile(input.SessionRef)
115→	if err != nil {
116→		return nil, fmt.Errorf("failed to read transcript: %w", err)
117→	}
118→
119→	return &agent.AgentSession{
120→		SessionID:  input.SessionID,
121→		AgentName:  c.Name(),
122→		SessionRef: input.SessionRef,
123→		StartTime:  time.Now(),
124→		NativeData: data,
125→	}, nil
126→}
127→
128→// WriteSession writes a session to Cursor's storage (JSONL transcript file).
129→func (c *CursorAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
130→	if session == nil {
131→		return errors.New("session is nil")
132→	}
133→
134→	if session.AgentName != "" && session.AgentName != c.Name() {
135→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
136→	}
137→
138→	if session.SessionRef == "" {
139→		return errors.New("session reference (transcript path) is required")
140→	}
141→
142→	if len(session.NativeData) == 0 {
143→		return errors.New("session has no native data to write")
144→	}
145→
146→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
147→		return fmt.Errorf("failed to write transcript: %w", err)
148→	}
149→
150→	return nil
151→}
152→
153→// FormatResumeCommand returns an instruction to resume a Cursor session.
154→// Cursor is a GUI IDE, so there's no CLI command to resume a session directly.
155→func (c *CursorAgent) FormatResumeCommand(_ string) string {
156→	return "Open this project in Cursor to continue the session."
157→}
158→
159→// sanitizePathForCursor converts a path to Cursor's project directory format.
160→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
161→
162→func sanitizePathForCursor(path string) string {
163→	path = strings.TrimLeft(path, "/")
164→	return nonAlphanumericRegex.ReplaceAllString(path, "-")
165→}
166→
167→// ChunkTranscript splits a JSONL transcript at line boundaries.
168→func (c *CursorAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
169→	chunks, err := agent.ChunkJSONL(content, maxSize)
170→	if err != nil {
171→		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
172→	}
173→	return chunks, nil
174→}
175→
176→// ReassembleTranscript concatenates JSONL chunks with newlines.
177→func (c *CursorAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
178→	return agent.ReassembleJSONL(chunks), nil
179→}
