 14→func TestParseHookEvent_UserPromptSubmitted(t *testing.T) {
 15→	t.Parallel()
 16→
 17→	ag := &CopilotCLIAgent{}
 18→	input := `{"timestamp":1771480081360,"cwd":"/path/to/repo","sessionId":"` + testSessionID + `","prompt":"hi"}`
 19→
 20→	event, err := ag.ParseHookEvent(context.Background(), HookNameUserPromptSubmitted, strings.NewReader(input))
 21→
 22→	if err != nil {
 23→		t.Fatalf("unexpected error: %v", err)
 24→	}
 25→	if event == nil {
 26→		t.Fatal("expected event, got nil")
 27→	}
 28→	if event.Type != agent.TurnStart {
 29→		t.Errorf("expected event type %v, got %v", agent.TurnStart, event.Type)
 30→	}
 31→	if event.SessionID != testSessionID {
 32→		t.Errorf("expected session_id %q, got %q", testSessionID, event.SessionID)
 33→	}
 34→	if event.Prompt != "hi" {
 35→		t.Errorf("expected prompt 'hi', got %q", event.Prompt)
 36→	}
 37→	if event.Timestamp.IsZero() {
 38→		t.Error("expected non-zero timestamp")
 39→	}
 40→}
