 14→// sampleTranscriptLines returns JSONL lines matching real Copilot CLI transcript format.
 15→func sampleTranscriptLines() []string {
 16→	return []string{
 17→		`{"type":"session.start","data":{"sessionId":"test-sess","version":1},"id":"c1","timestamp":"2026-03-02T01:00:00Z","parentId":null}`,
 18→		`{"type":"user.message","data":{"content":"hello","interactionId":"i1"},"id":"u1","timestamp":"2026-03-02T01:00:01Z","parentId":"c1"}`,
 19→		`{"type":"assistant.turn_start","data":{"turnId":"0","interactionId":"i1"},"id":"t1","timestamp":"2026-03-02T01:00:02Z","parentId":"u1"}`,
 20→		`{"type":"assistant.message","data":{"content":"Hi there!","toolRequests":[],"interactionId":"i1"},"id":"m1","timestamp":"2026-03-02T01:00:03Z","parentId":"t1"}`,
 21→		`{"type":"assistant.turn_end","data":{"turnId":"0"},"id":"te1","timestamp":"2026-03-02T01:00:04Z","parentId":"m1"}`,
 22→	}
 23→}
