 25→func writeSampleTranscript(t *testing.T, dir string) string {
 26→	t.Helper()
 27→	path := filepath.Join(dir, "events.jsonl")
 28→	content := strings.Join(sampleTranscriptLines(), "\n") + "\n"
 29→	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
 30→		t.Fatalf("failed to write sample transcript: %v", err)
 31→	}
 32→	return path
 33→}
