56→func (c *CopilotCLI) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
57→	cfg := &runConfig{}
58→	for _, o := range opts {
59→		o(cfg)
60→	}
61→
62→	timeout := 60 * time.Second
63→	if cfg.PromptTimeout > 0 {
64→		timeout = cfg.PromptTimeout
65→	}
66→	promptCtx, cancel := context.WithTimeout(ctx, timeout)
67→	defer cancel()
68→
69→	args := []string{"-p", prompt, "--allow-all-tools"}
70→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--allow-all-tools"}
